using System;using System.Reflection;using System.Xml;using System.Globalization;
class Program{
 delegate int SpanCheck(ReadOnlySpan<char> value);
 static MethodInfo Method(Type t,string n,params Type[] types)=>t.GetMethod(n,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static,null,types,null)!;
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;var assembly=typeof(XmlDocument).Assembly;var t=assembly.GetType("System.Xml.XmlCharType")!;var names=assembly.GetType("System.Xml.ValidateNames")!;var ws=Method(t,"IsOnlyWhitespaceWithPos",typeof(ReadOnlySpan<char>)).CreateDelegate<SpanCheck>();var cd=Method(t,"IsOnlyCharData",typeof(ReadOnlySpan<char>)).CreateDelegate<SpanCheck>();var pi=Method(t,"IsPublicId",typeof(string)).CreateDelegate<Func<string,int>>();var properties=Method(t,"GetCharProperties",typeof(char)).CreateDelegate<Func<char,uint>>();var nc=Method(names,"ParseNCName",typeof(string),typeof(int)).CreateDelegate<Func<string,int,int>>();var name=Method(names,"ParseNameNoNamespaces",typeof(string),typeof(int)).CreateDelegate<Func<string,int,int>>();var token=Method(names,"ParseNmtoken",typeof(string),typeof(int)).CreateDelegate<Func<string,int,int>>();var tokenNo=Method(names,"ParseNmtokenNoNamespaces",typeof(string),typeof(int)).CreateDelegate<Func<string,int,int>>();var q=Method(names,"ParseQName",typeof(string),typeof(int),typeof(int).MakeByRefType());string? line;while((line=Console.ReadLine())!=null){int offset=0;int separator=line.IndexOf(' ');if(separator>=0){offset=int.Parse(line.Substring(0,separator));line=line.Substring(separator+1);}string s="";if(line!="-"){char[] chars=new char[line.Length/4];for(int i=0;i<chars.Length;i++)chars[i]=(char)Convert.ToUInt16(line.Substring(i*4,4),16);s=new string(chars);}object[] args={s,offset,0};int len=(int)q.Invoke(null,args)!;Console.Write(ws(s)+" "+cd(s)+" "+pi(s)+" "+nc(s,offset)+" "+name(s,offset)+" "+token(s,offset)+" "+tokenNo(s,offset)+" "+len+" "+args[2]);if(s.Length==1)Console.Write(" "+properties(s[0]));Console.WriteLine();}}
}
